export function updateBody({ position, normal, index, matrix, size }: {
    position: any;
    normal: any;
    index: any;
    matrix: any;
    size: any;
}, type: any, bodyIndex: any, matrixWorlds: any): void;
export function addBody({ position, normal, index, faceGeoId, uv, matrix, size, side, geoType, isPoints, }: {
    position: any;
    normal: any;
    index: any;
    faceGeoId: any;
    uv: any;
    matrix: any;
    size: any;
    side?: any;
    geoType: any;
    isPoints?: boolean;
}, type: any, properties: any, wallBox: any, bodyProps?: {}): any;
/**
 * Add multiple physics bodies in a single batch operation.
 * This is significantly faster than calling addBody multiple times
 * because it avoids repeated RPC overhead.
 *
 * @param {Array<Object>} bodiesData - Array of body data objects.
 * @param {Object} bodiesData[].geometry - Geometry data (position, index, normal, faceGeoId, side).
 * @param {Object} bodiesData[].properties - Physics properties (friction, mass, etc.).
 * @param {Object} bodiesData[].bodyProps - Body properties (capsuleRadius, etc.).
 * @param {Object} bodiesData[].wallBox - Optional wall box data.
 * @param {string} type - Body type for all bodies in batch.
 * @returns {Array<number>} Array of assigned indices.
 * @private
 */
export function addBodies(bodiesData: Array<any>, type: string): Array<number>;
export function removeBody(type: any, index: any): string;
export function addKinematicCollideManager(index: any, collideManager: any): string;
export function registerInReach(position: any, props: any): number;
export function unregisterInReach(index: any): string;
export function toggleBodyProp(type: any, index: any, prop: any, val: any): string;
export function setBodySAB(type: any, index: any, SABName: any, SAB: any): string;
export function toggleSide(type: any, index: any, side?: any): string;
export function toggleKinematicBodyAttr(index: any, prop: any): string;
export function registerPath(pathId: any, points: any, closedPath: any, closingCurveControls: any, transformMatrix: any): string;
export function makeParent(index: any, childIndex: any): string;
export function addToTree(index: any): string;
export function updateKinematicAndChildsOnce(index: any): string;
/**
 * Configure frustum culling for physics collision detection.
 * @param {Object} config - Configuration options.
 * @param {number} [config.margin] - Padding in world units (default: 10).
 * @param {number} [config.near] - Near plane distance (default: 0.1).
 * @param {number} [config.far] - Far plane distance (default: 1000).
 * @param {boolean} [config.enabled] - Enable/disable frustum culling (default: true).
 * @returns {string}
 */
export function setFrustumConfig(config: {
    margin?: number;
    near?: number;
    far?: number;
    enabled?: boolean;
}): string;
/**
 * Configure spatial grid for physics collision detection.
 * @param {Object} config - Configuration options.
 * @param {number} [config.cellSize] - Size of each grid cell in world units (default: 4).
 * @param {boolean} [config.enabled] - Enable/disable spatial grid (default: true).
 * @returns {string}
 */
export function setSpatialGridConfig(config: {
    cellSize?: number;
    enabled?: boolean;
}): string;
